    ["еЃ¶йЃ‡ж–Їжћ—е¤Єе¤Є"] = "РќР°С‚РєРЅСѓР»СЃСЏ РЅР° РјРёСЃСЃРёСЃ РЎС‚Р°Р№Р»РёРЅРі",
    ["Defeat the thief leader"] = "РџРѕР±РµРґРёС‚СЊ РіР»Р°РІР°СЂСЏ РІРѕСЂРѕРІ",
    ["Today is the happiest day of Jenny's life; Jenny has never been this happy before. Jenny will keep these memories tucked away deep in her heart."] = "РЎРµРіРѕРґРЅСЏ СЃР°РјС‹Р№ СЃС‡Р°СЃС‚Р»РёРІС‹Р№ РґРµРЅСЊ РІ Р¶РёР·РЅРё Р”Р¶РµРЅРЅРё; Р”Р¶РµРЅРЅРё РЅРёРєРѕРіРґР° СЂР°РЅСЊС€Рµ РЅРµ Р±С‹Р»Р° С‚Р°РєРѕР№ СЃС‡Р°СЃС‚Р»РёРІРѕР№. Р”Р¶РµРЅРЅРё СЃРѕС…СЂР°РЅРёС‚ СЌС‚Рё РІРѕСЃРїРѕРјРёРЅР°РЅРёСЏ РіР»СѓР±РѕРєРѕ РІ СЃРІРѕРµРј СЃРµСЂРґС†Рµ.",
    ["<DecH> Craft: </> Jumping Ornament \n Ripples surge, and bright golden-orange breaks through the rolling heat waves. Water splashes, summer is here!"] = "<DecH>Р РµРјРµСЃР»Рѕ: <Assistant_Property2>РўР°РЅС†СѓСЋС‰Р°СЏ РїРѕРґРІРµСЃРєР°\nР’РѕР»РЅС‹ РЅР°РєР°С‚С‹РІР°СЋС‚, Рё СЃРѕС‡РЅС‹Р№ Р·РѕР»РѕС‚РёСЃС‚Рѕ-РѕСЂР°РЅР¶РµРІС‹Р№ С†РІРµС‚ РїСЂРѕРЅР·Р°РµС‚ РєР»СѓР±СЏС‰РёР№СЃСЏ Р·РЅРѕР№. Р‘СЂС‹Р·РіРё РІРѕРґС‹ вЂ” Р»РµС‚Рѕ РІ СЃР°РјРѕРј СЂР°Р·РіР°СЂРµ!",
    ["Taking a quarter of an hour to smoke a pipe and letting the smell of smoke dissipate on the way home is the break time I give myself."] = "Р’С‹РґРµР»РёС‚СЊ С‡РµС‚РІРµСЂС‚СЊ С‡Р°СЃР° РЅР° С‚Рѕ, С‡С‚РѕР±С‹ РІС‹РєСѓСЂРёС‚СЊ С‚СЂСѓР±РєСѓ Рё РїРѕР·РІРѕР»РёС‚СЊ Р·Р°РїР°С…Сѓ РґС‹РјР° СЂР°СЃСЃРµСЏС‚СЊСЃСЏ РїРѕ РґРѕСЂРѕРіРµ РґРѕРјРѕР№, вЂ” СЌС‚Рѕ РІСЂРµРјСЏ РїРµСЂРµСЂС‹РІР°, РєРѕС‚РѕСЂРѕРµ СЏ РґР°СЋ СЃРµР±Рµ.",
    ["What's the matter? Let me tell you, I'm not slacking off."] = "Р’ С‡РµРј РґРµР»Рѕ? РЎРєР°Р¶Сѓ РІР°Рј, СЏ РЅРµ СЂР°СЃСЃР»Р°Р±Р»СЏСЋСЃСЊ.",
    ["Has anyone ever told you that you are very bad at lying?"] = "РљС‚Рѕ-РЅРёР±СѓРґСЊ РєРѕРіРґР°-РЅРёР±СѓРґСЊ РіРѕРІРѕСЂРёР» С‚РµР±Рµ, С‡С‚Рѕ С‚С‹ РѕС‡РµРЅСЊ РїР»РѕС…Рѕ Р»Р¶РµС€СЊ?",
    ["й’¦е·ћ"] = "Р¦РёРЅСЊС‡Р¶РѕСѓ",
    ["Normal Selena"] = "РќРѕСЂРјР°Р»СЊРЅР°СЏ РЎРµР»РµРЅР°",
    ["ж–№жЎ€%s"] = "РЎС…РµРјР° %s",
    ["еЋ»еђ§пјЊж‰“ејЂзњ‹зњ‹дЅ е°±жЋз™Ѕдє†гЂ‚"] = "Р”Р°РІР°Р№, РѕС‚РєСЂРѕР№ Рё С‚С‹ РїРѕР№РјРµС€СЊ.",
    ["Violent souls, but only\nThe stuffed men\nWe circle round the swamp\nWater Lily, Water Lily\nWe circle round the swamp\nAt five o'clock in the morning\n\nBetween the idea and the reality\nBetween the motion and the act\nFalls the Shadow\nWhere it belongs"] = "Р‘СѓР№РЅС‹Рµ РґСѓС€Рё, РЅРѕ Р»РёС€СЊ\nРќР°Р±РёС‚С‹Рµ СЃРѕР»РѕРјРѕР№ С‡СѓС‡РµР»Р°\nРњС‹ РєСЂСѓР¶РёРј РІРѕРєСЂСѓРі Р±РѕР»РѕС‚Р°\nРљСѓРІС€РёРЅРєР°, РєСѓРІС€РёРЅРєР°\nРњС‹ РєСЂСѓР¶РёРј РІРѕРєСЂСѓРі Р±РѕР»РѕС‚Р°\nР’ РїСЏС‚СЊ С‡Р°СЃРѕРІ РїРѕСѓС‚СЂСѓ\n\nРњРµР¶РґСѓ Р·Р°РјС‹СЃР»РѕРј Рё РІРѕРїР»РѕС‰РµРЅРёРµРј\nРњРµР¶РґСѓ РґРІРёР¶РµРЅРёРµРј Рё РїРѕСЃС‚СѓРїРєРѕРј\nРџР°РґР°РµС‚ РўРµРЅСЊ\nРўСѓРґР°, РіРґРµ РµР№ РјРµСЃС‚Рѕ",
    ["After keeping spirit pets and collecting more and more antiques, I feel that I have gradually developed a kind of \"mediumship\" ability. My heart has been thumping these past few days. When I go home from work at the factory outside the town, I don't dare to take the road by the ancient castle. Seeing the notice board in town today, it said that a family of four, who were low-sequence residents, had been killed. I actually especially associated it with whether I would be the next one? I have a premonition that something big will happen tonight. But thanks to the antiques I collected, and my cute spirit snakes and spirit mice, I am especially excited now, as if someone will help me solve these things... I will close the windows and doors tightly and put \"that thing\" by the bed. If it really comes, I will..."] = "Р—Р°РІРµРґСЏ РґСѓС…РѕРІРЅС‹С… РїРёС‚РѕРјС†РµРІ Рё СЃРѕР±РёСЂР°СЏ РІСЃРµ Р±РѕР»СЊС€Рµ Рё Р±РѕР»СЊС€Рµ Р°РЅС‚РёРєРІР°СЂРёР°С‚Р°, СЏ С‡СѓРІСЃС‚РІСѓСЋ, С‡С‚Рѕ РїРѕСЃС‚РµРїРµРЅРЅРѕ СЂР°Р·РІРёР» РІ СЃРµР±Рµ СЃРІРѕРµРіРѕ СЂРѕРґР° В«РјРµРґРёСѓРјРёС‡РµСЃРєРёРµВ» СЃРїРѕСЃРѕР±РЅРѕСЃС‚Рё. РњРѕС‘ СЃРµСЂРґС†Рµ РєРѕР»РѕС‚РёР»РѕСЃСЊ РїРѕСЃР»РµРґРЅРёРµ РЅРµСЃРєРѕР»СЊРєРѕ РґРЅРµР№. РљРѕРіРґР° СЏ РёРґСѓ РґРѕРјРѕР№ СЃ СЂР°Р±РѕС‚С‹ РЅР° С„Р°Р±СЂРёРєРµ Р·Р° РіРѕСЂРѕРґРѕРј, СЏ РЅРµ РѕСЃРјРµР»РёРІР°СЋСЃСЊ РёРґС‚Рё РїРѕ РґРѕСЂРѕРіРµ РјРёРјРѕ СЃС‚Р°СЂРёРЅРЅРѕРіРѕ Р·Р°РјРєР°. РЈРІРёРґРµРІ СЃРµРіРѕРґРЅСЏ РІ РіРѕСЂРѕРґРµ РґРѕСЃРєСѓ РѕР±СЉСЏРІР»РµРЅРёР№, С‚Р°Рј Р±С‹Р»Рѕ РЅР°РїРёСЃР°РЅРѕ, С‡С‚Рѕ Р±С‹Р»Р° СѓР±РёС‚Р° СЃРµРјСЊСЏ РёР· С‡РµС‚С‹СЂРµС… С‡РµР»РѕРІРµРє, РєРѕС‚РѕСЂС‹Рµ РїСЂРѕР¶РёРІР°Р»Рё РІ РЅРµР±РѕР»СЊС€РёС… РєРѕР»РёС‡РµСЃС‚РІР°С…. РќР° СЃР°РјРѕРј РґРµР»Рµ Сѓ РјРµРЅСЏ СЌС‚Рѕ РѕСЃРѕР±РµРЅРЅРѕ Р°СЃСЃРѕС†РёРёСЂРѕРІР°Р»РѕСЃСЊ СЃ С‚РµРј, Р±СѓРґСѓ Р»Рё СЏ СЃР»РµРґСѓСЋС‰РёРј? РЈ РјРµРЅСЏ РїСЂРµРґС‡СѓРІСЃС‚РІРёРµ, С‡С‚Рѕ СЃРµРіРѕРґРЅСЏ РІРµС‡РµСЂРѕРј РїСЂРѕРёР·РѕР№РґРµС‚ С‡С‚Рѕ-С‚Рѕ Р±РѕР»СЊС€РѕРµ. РќРѕ Р±Р»Р°РіРѕРґР°СЂСЏ СЃРѕР±СЂР°РЅРЅРѕРјСѓ РјРЅРѕСЋ Р°РЅС‚РёРєРІР°СЂРёР°С‚Сѓ, РјР